import{z as A,x as d,o as r,c as p,q as t,j as n,D as e,d as o,s as l,S as s,b as i}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"协议形式化 ProVerif / Tamarin","description":"","frontmatter":{"title":"协议形式化 ProVerif / Tamarin","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/protocol-verification.md","filePath":"cs/protocol-verification.md","lastUpdated":1791063341000}'),B={name:"cs/protocol-verification.md"};function c(m,a,h,f,T,D){const E=d("Mermaid");return r(),p("div",null,[a[2]||(a[2]=t('<h1 id="协议形式化-proverif-tamarin" tabindex="-1">协议形式化 ProVerif / Tamarin <a class="header-anchor" href="#协议形式化-proverif-tamarin" aria-label="Permalink to &quot;协议形式化 ProVerif / Tamarin&quot;">​</a></h1><div class="epigraph"><p>符号模型把加密当理想锁，穷举角色与消息，问保密与认证是否在 Dolev–Yao 下可破。ProVerif 与 Tamarin 把这份穷举收成工具；证明的是模型，不是 C 代码。</p><footer>—— Blanchet, ProVerif；Meier, Schmidt, Cremers 与 Basin, Tamarin；Dolev and Yao, 1983</footer></div><p>上一课<a href="/cs/biometrics-far-frr">生物识别</a>结束因素课。缺口是把<a href="/cs/dolev-yao">Dolev–Yao</a>变成<strong>可跑的验证</strong>：Needham–Schroeder 下一课就是经典反例。本课工具直觉，不教安装，不重写 TLA+。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>手工论证易漏角色交错。符号工具：规则重写或 Horn 子句，查询「攻击者能得到 nonce 吗」。计算模型（CryptoVerif 等）更近归约，更贵。缺口是模型边界：计时、填充预言、代数都可能在符号外。</p><h3 id="找到攻击是强结果" tabindex="-1">找到攻击是强结果 <a class="header-anchor" href="#找到攻击是强结果" aria-label="Permalink to &quot;找到攻击是强结果&quot;">​</a></h3><p>「无攻击」相对于模型。漏掉一条信道就漏攻击。Lowe 的修复正是模型里多出来的身份字段。</p><p><span class="marginnote">Blanchet 的 ProVerif；Tamarin 的多重集重写。本课不把工具当 seL4 那种 C 验证。</span></p><p><span class="marginnote">可以把符号模型里的加密想象成理想保险箱：Dolev–Yao 攻击者是快递网里的恶意快递员——能拆开外包装看、扣下包裹、投假包裹、把旧包裹重投一遍，但撬不开箱子本身；没有私钥，密文对他就是一块石头。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写协议为规则；标秘密与对应性断言（认证）。指出无界会话是难点，要抽象。下一课用 NSL 把「工具为谁发明」讲成故事。</p>',12)),(r(),n(s,null,{default:e(()=>[l(E,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SPEC%5B%22%E7%AC%A6%E5%8F%B7%E5%8D%8F%E8%AE%AE%22%5D%20--%3E%20TOOL%5B%22ProVerif%20%2F%20Tamarin%22%5D%0A%20%20TOOL%20--%3E%20SEC%5B%22%E4%BF%9D%E5%AF%86%E6%9F%A5%E8%AF%A2%22%5D%0A%20%20TOOL%20--%3E%20AUTH%5B%22%E5%AF%B9%E5%BA%94%E6%80%A7%E8%AE%A4%E8%AF%81%22%5D%0A%20%20MODEL%5B%22%E6%A8%A1%E5%9E%8B%E5%A4%96%E9%80%9A%E9%81%93%22%5D%20-.-%3E%20SIL%5B%22%E5%B7%A5%E5%85%B7%E6%B2%89%E9%BB%98%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("h2",{id:"机制",tabindex:"-1"},[o("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=i("p",null,"形式化把身份单元从「清单」升到「可证的交错」。下一课 Needham–Schroeder：经典认证协议如何在模型里被 Lowe 指出漏洞。",-1)),(r(),n(s,null,{default:e(()=>[l(E,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%AF%9A%E5%AE%9E%E6%96%B9%20A%20%E5%8F%91%E5%87%BA%E6%B6%88%E6%81%AF%22%5D%20--%3E%20NET%5B%22%E7%BD%91%E7%BB%9C%E4%BF%A1%E9%81%93%22%5D%0A%20%20NET%20--%3E%20B%5B%22%E8%AF%9A%E5%AE%9E%E6%96%B9%20B%20%E6%94%B6%E5%88%B0%E6%B6%88%E6%81%AF%22%5D%0A%20%20ATK%5B%22Dolev-Yao%20%E6%94%BB%E5%87%BB%E8%80%85%22%5D%20-.%E7%AA%83%E5%90%AC%E5%85%A8%E9%83%A8%E6%B5%81%E9%87%8F.-%3E%20NET%0A%20%20ATK%20-.%E7%AF%A1%E6%94%B9%E6%88%96%E9%87%8D%E6%94%BE.-%3E%20NET%0A%20%20ATK%20-.%E7%94%A8%E5%B7%B2%E7%9F%A5%E5%AF%86%E9%92%A5%E4%BC%AA%E9%80%A0%E6%96%B0%E6%B6%88%E6%81%AF.-%3E%20NET%0A%20%20ATK%20-.%E6%97%A0%E7%A7%81%E9%92%A5%E6%95%85%E6%97%A0%E6%B3%95%E8%A7%A3%E5%AF%86.-%3E%20NET%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">上图回答「符号工具替你穷举的那个敌人长什么样」：攻击者坐在信道上，四件事随便做（听、改、重放、造），一件事永远做不了（无密钥的解密）。工具的查询就是在问：这样折腾几轮之后，nonce 会不会漏进他的知识库里。</span></p><p><span class="marginnote">初学者容易以为工具说「无攻击」就等于协议安全。实际上结论只对写进模型的信道与能力负责：漏写一条侧信道（计时、报错提示、填充预言），攻击就恰好藏在工具沉默的那块地方。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不验证 TLS 全文。Needham–Schroeder 与 Lowe 下一课。</p><p><span class="marginnote">找到攻击是强结果：工具给出一条具体的消息交错序列，人可以照着重演攻击；而「模型内无攻击」只是与模型同宽的弱结论。一强一弱，读工具输出时要分清自己拿到的是哪一个。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>因素课之后，用符号工具看协议交错。</li><li>ProVerif/Tamarin 证明模型内的保密与认证。</li><li>计时与实现通道在模型外。</li><li>下一课：NS 与 Lowe 修正。</li><li>出处：Dolev and Yao, 1983；Blanchet；Meier et al., Tamarin。</li></ul>',7))])}const P=A(B,[["render",c]]);export{u as __pageData,P as default};
